// ============================================
// PROJECT NAME + TIMELINE
// MULTIPLE ITEMS
// ============================================

const sheetData =
$('updated sheet data')
.first()
.json
.sheet_data;

const rawSheetName =
$('job type for template')
.first()
.json
.job_type;

const SHEET_NAME =
"'" + String(rawSheetName).trim() + "'";

const skipRows = {
  3: true
};

const items = [];

// ============================================
// ROW 2 -> PROJECT NAME
// ============================================

const row2 =
sheetData.find(
  r => Number(r.row_number) === 2
);

if (row2) {

  items.push({
    json: {

      range:
        SHEET_NAME + '!A2',

      values: [[
        String(row2.col_1 || '')
      ]]

    }
  });

}

// ============================================
// PROJECT TIMELINE
// COLUMN B
// ============================================

for (const row of sheetData) {

  const rowNumber =
    Number(row.row_number);

  if (!rowNumber) continue;

  if (skipRows[rowNumber]) {
    continue;
  }

  if (rowNumber >= 4) {

    items.push({

      json: {

        range:
          SHEET_NAME +
          '!B' +
          rowNumber,

        values: [[
          String(
            row['PROJECT TIMELINE'] || ''
          )
        ]]

      }

    });

  }

}

return items;

