.job_type;

const SHEET_NAME =
"'" + String(rawSheetName).trim() + "'";

const skipRows = {
  3: true
};

const items = [];

for (const row of sheetData) {

  const rowNumber =
    Number(row.row_number);

  if (!rowNumber) continue;

  if (skipRows[rowNumber]) {
    continue;
  }

  if (rowNumber >= 4) {

    items.push({

      json: {

        range:
          SHEET_NAME +
          '!D' +
          rowNumber +
          ':E' +
          rowNumber,

        values: [[

          String(row.col_4 || ''),
          String(row.col_5 || '')

        ]]

      }

    });

  }

}

return items;

const sheet = $input.first().json.sheet;

// Find Production section
const productionHeaderIndex = sheet.findIndex(
  row =>
    row.col_1 &&
    row.col_1.toString().trim().toLowerCase() === "production"
);

if (productionHeaderIndex === -1) {
  throw new Error("Production section not found");
}

// Get rows after Production header
const productionRows = [];

for (let i = productionHeaderIndex + 1; i < sheet.length; i++) {
  const row = sheet[i];

  // Section header = empty timeline + empty days
  const isSectionHeader =
    !row["PROJECT TIMELINE"] &&
    !row.col_3 &&
    row.col_1;

  if (isSectionHeader) {
    break;
  }

  if (
    row["PROJECT TIMELINE"] &&
    row.col_4 &&
    row.col_5
  ) {
    productionRows.push(row);
  }
}

if (!productionRows.length) {
  throw new Error("No production timeline rows found");
}

const startDate = productionRows[0].col_4.trim();
const endDate = productionRows[productionRows.length - 1].col_5.trim();

const totalDays = productionRows.reduce(
  (sum, row) => sum + (Number(row.col_3) || 0),
  0
);

const milestones = productionRows.map(row => ({
  milestone_name: row.col_1,
  start_date: row.col_4.trim(),
  end_date: row.col_5.trim(),
  days_allocated: Number(row.col_3) || 0
}));

return [
  {
    json: {
      project_timeline: {
        milestone_name: "Production",
        start_date: startDate,
        end_date: endDate,
        days_allocated: totalDays,
        task_count: productionRows.length,
        milestones
      }
    }
  }
];

